scwin.trigger1_onclick = function(e) {
	var options = {};
	options.type = "1";
	options.fileName = "excelData.xls";
	options.bodyTextAlign = "right";
	options.autoSizeColumn = "true";
	options.useDataFormat = "true";
	tbl1.pivotExcelDownload(options);
};
